def run():
    print("Seeding 33 FAQ items into database...")
    created_count = 0
    for item in FAQS_DATA:
        faq, created = FAQ.objects.update_or_create(
            order=item['order'],
            defaults={
                'question': item['question'],
                'answer': item['answer'],
                'category': item['category'],
            }
        )
        if created:
            created_count += 1
    print(f"Successfully seeded {len(FAQS_DATA)} FAQ items! ({created_count} new entries created)")

if __name__ == '__main__':
    run()
